<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://southcarolinainsuranceappraiser.com/#business","name":"South Carolina Insurance Appraiser","url":"https://southcarolinainsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@southcarolinainsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://southcarolinainsuranceappraiser.com/#logo","url":"https://southcarolinainsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"South Carolina Insurance Appraiser"},"image":{"@id":"https://southcarolinainsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"SC","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@southcarolinainsuranceappraiser.com","contactType":"customer service","areaServed":"US-SC","availableLanguage":"en"}],"description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across all 46 South Carolina counties.","areaServed":[{"@type":"State","name":"South Carolina"},{"@type":"City","name":"Charleston"},{"@type":"City","name":"Columbia"},{"@type":"City","name":"Greenville"},{"@type":"City","name":"Myrtle Beach"},{"@type":"City","name":"Spartanburg"},{"@type":"City","name":"Mount Pleasant"},{"@type":"City","name":"Summerville"},{"@type":"City","name":"Rock Hill"},{"@type":"City","name":"Hilton Head Island"},{"@type":"City","name":"Florence"},{"@type":"City","name":"Beaufort"},{"@type":"City","name":"Aiken"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Demand Representation","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/appraisal-demand-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Home Insurance Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Claim Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/wind-tornado-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane Claim Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/hurricane-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Claim Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/water-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tree Fall & Ice Storm Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/tree-fall-ice-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Earthquake Claim Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/earthquake-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Claim Estimate Review","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/claim-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire & Neutral Appraiser","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/umpire-neutral-appraiser/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Hurricane claims","Wind and flood causation","Xactimate estimating","Umpire services"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://southcarolinainsuranceappraiser.com/#website","url":"https://southcarolinainsuranceappraiser.com/","name":"South Carolina Insurance Appraiser","publisher":{"@id":"https://southcarolinainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/#webpage","url":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/","name":"Insurance Appraisal FAQ: Costs, Timing & SC Rules","description":"Insurance appraisal FAQ for South Carolina: how appraisal works, costs, timing, hurricane deductibles, the wind pool and when awards bind.","inLanguage":"en-US","isPartOf":{"@id":"https://southcarolinainsuranceappraiser.com/#website"},"about":{"@id":"https://southcarolinainsuranceappraiser.com/#business"},"publisher":{"@id":"https://southcarolinainsuranceappraiser.com/#business"},"dateModified":"2026-11-12","primaryImageOfPage":{"@id":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/#primaryimage"},"breadcrumb":{"@id":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/#breadcrumb"},"mainEntity":{"@id":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/#faqpage"}},{"@type":"ImageObject","@id":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/#primaryimage","url":"https://southcarolinainsuranceappraiser.com/assets/img/photos/living-room.webp","width":1200,"height":800,"caption":"Living room with a sofa, armchair and ceiling fan"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://southcarolinainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Insurance appraisal FAQ","item":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/"}],"@id":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What does an insurance appraiser actually do?","acceptedAnswer":{"@type":"Answer","text":"An insurance appraiser values the cost to repair or replace damaged property under the terms of a policy. When you and your insurer agree a loss is covered but disagree on the price, each side names an appraiser, and those two try to agree on the amount of loss, with an umpire breaking any deadlock."}},{"@type":"Question","name":"Is appraisal the same as going to court?","acceptedAnswer":{"@type":"Answer","text":"No. Appraisal is a private process written into your policy, and it normally decides only the amount of loss. A lawsuit can address coverage, contract interpretation and other legal claims. For anything beyond price, talk with a South Carolina attorney."}},{"@type":"Question","name":"Who can invoke appraisal?","acceptedAnswer":{"@type":"Answer","text":"Either party: you or the insurance company. The demand should be in writing, cite the appraisal provision in your policy and state that the parties disagree on the amount of loss."}},{"@type":"Question","name":"Is the appraisal award binding?","acceptedAnswer":{"@type":"Answer","text":"On the amount of loss, generally yes, once any two of the three panel members sign. Courts can set awards aside in limited situations, such as fraud, a biased panel member or a panel deciding questions outside its authority."}},{"@type":"Question","name":"Does appraisal work for commercial and HOA claims?","acceptedAnswer":{"@type":"Answer","text":"Yes. Commercial, condominium association and HOA master policies usually carry an appraisal clause that works the same way. Those claims often involve more buildings, more trades and contents or business income, so they tend to take longer."}},{"@type":"Question","name":"How are insurance appraisers paid?","acceptedAnswer":{"@type":"Answer","text":"Arrangements vary. Some appraisers bill hourly, some charge a flat fee and some work for a percentage of the award or of the increase over the insurer’s number. Whatever the structure, get it in writing before you sign."}},{"@type":"Question","name":"Who pays the umpire?","acceptedAnswer":{"@type":"Answer","text":"Under most policy wording, each side pays its own appraiser and the two sides share the umpire’s fee equally. Check your policy, because some carriers use different language."}},{"@type":"Question","name":"Is appraisal worth it for a small gap?","acceptedAnswer":{"@type":"Answer","text":"Often not. If the difference between estimates is only a few thousand dollars, appraisal fees can eat most of the gain. A well-documented supplement request or a call to the adjuster’s supervisor may be the better first step."}},{"@type":"Question","name":"Can I recover appraisal costs from the insurer?","acceptedAnswer":{"@type":"Answer","text":"Usually the policy says each side bears its own appraisal costs. Whether any fees can be shifted in a later dispute is a legal question that depends on the facts, so ask a South Carolina attorney rather than assuming either way."}},{"@type":"Question","name":"How long does appraisal take in South Carolina?","acceptedAnswer":{"@type":"Answer","text":"Many residential appraisals wrap up within two to four months of the demand, depending on how fast both appraisers are named and whether an umpire is needed. Large commercial, condo or contents claims, and periods right after a major hurricane, can stretch that timeline."}},{"@type":"Question","name":"Is there a deadline to demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Some policies set one and many don’t, but waiting too long can create arguments about waiver. Separately, your policy may set a deadline to file suit, and South Carolina contract claims generally carry a three-year limitation period. Confirm with a South Carolina attorney how those rules apply to your claim."}},{"@type":"Question","name":"How quickly must each side name its appraiser?","acceptedAnswer":{"@type":"Answer","text":"Many policies give each side 20 days from the demand to name an appraiser and give the appraisers 15 days to agree on an umpire. Calendar those dates the day the demand goes out or arrives."}},{"@type":"Question","name":"Does appraisal pause my deadline to sue?","acceptedAnswer":{"@type":"Answer","text":"Not automatically. Depending on the policy wording and the facts, the suit-limitation clock may keep running during appraisal. If your deadline is getting close, speak with a South Carolina attorney before relying on appraisal alone."}},{"@type":"Question","name":"When does the insurer have to pay after an award?","acceptedAnswer":{"@type":"Answer","text":"The policy usually sets a payment window after the award is signed, often measured in days. Expect the deductible and prior payments to come off, recoverable depreciation to be held until repairs are complete, and your mortgage lender to be named on the check."}},{"@type":"Question","name":"How do hurricane deductibles work in South Carolina?","acceptedAnswer":{"@type":"Answer","text":"Many coastal policies use a hurricane or named-storm deductible set as a percentage of the dwelling limit, often 1% to 5% or more, instead of a flat dollar amount. Whether it applies depends on the trigger wording in your policy, such as a watch or warning being issued. Check the declarations page, where the deductible must be disclosed."}},{"@type":"Question","name":"Does a wind pool policy from SCWHUA include appraisal?","acceptedAnswer":{"@type":"Answer","text":"The South Carolina Wind and Hail Underwriting Association insures wind and hail in designated coastal areas, and its policies, like most property forms, generally contain an appraisal provision. Read your current SCWHUA policy for the exact wording, and remember that your homeowners and flood policies are handled separately."}},{"@type":"Question","name":"Can flood damage go to appraisal?","acceptedAnswer":{"@type":"Answer","text":"Flood is excluded from standard homeowners policies and is covered by a separate NFIP or private flood policy. The NFIP’s standard flood policy has its own appraisal provision and strict proof-of-loss rules set by federal regulation. Private flood policies follow their own wording."}},{"@type":"Question","name":"Where can I complain about how my claim was handled?","acceptedAnswer":{"@type":"Answer","text":"The South Carolina Department of Insurance (SCDOI) accepts consumer complaints and licenses adjusters. A complaint can prompt a response from the carrier, but SCDOI doesn’t set the value of your loss. Questions about bad faith or unfair claims practices are for a South Carolina attorney."}},{"@type":"Question","name":"What happens if the appraisers can’t agree on an umpire?","acceptedAnswer":{"@type":"Answer","text":"Most policies let either side ask a court of record in the county where the property is located to appoint one. In South Carolina, that is the circuit court for the county, and the request is a short filing that an attorney typically handles."}},{"@type":"Question","name":"What do you need to review my claim?","acceptedAnswer":{"@type":"Answer","text":"Send the full policy and declarations page, the insurer’s estimate, any contractor estimates, correspondence with the adjuster and your photos. With those, we can tell you whether the gap looks like an amount dispute that suits appraisal."}},{"@type":"Question","name":"Are you a public adjuster or a law firm?","acceptedAnswer":{"@type":"Answer","text":"Neither. We are an independent insurance appraisal practice. We serve as appraiser, estimate reviewer or umpire on disputed property claims. We don’t negotiate the claim as a public adjuster would, and we don’t give legal advice."}},{"@type":"Question","name":"Do you serve my part of South Carolina?","acceptedAnswer":{"@type":"Answer","text":"We work on claims statewide, from the Upstate and Midlands to the Pee Dee, the Grand Strand and the Lowcountry. Inspections are scheduled around the claim, and much of the estimate work can be done from your documents."}},{"@type":"Question","name":"Can you act as an umpire?","acceptedAnswer":{"@type":"Answer","text":"Yes, when both appraisers agree to appoint us or a court does. As an umpire, we stay neutral and decide only the items the two appraisers can’t resolve."}},{"@type":"Question","name":"Will you tell me if appraisal isn’t a good fit?","acceptedAnswer":{"@type":"Answer","text":"Yes. If the gap is small, the dispute is really about coverage, or a legal deadline is close, we’ll say so plainly and suggest other routes, including speaking with a South Carolina attorney."}}],"@id":"https://southcarolinainsuranceappraiser.com/insurance-appraisal-faq/#faqpage"}]}</script>
</head>
